// Contract foundry.research/v1 — the only thing Requstory and the foundry share.
// Generated by hand from knowledge-foundry/src/foundry/research.py; the JSON
// Schemas in ../schema are the source of truth if the two ever disagree.

export const CONTRACT = "foundry.research/v1" as const;

/** Evidence from registers and the company's own site may be shown to anyone.
 *  Press, reviews and community evidence is shown only to the company, once it
 *  has claimed its page. Every piece of evidence carries one of these. */
export type Visibility = "public" | "claimant_only";

export type SourceType =
  | "official_record" | "self_published" | "press" | "review" | "community";

export interface ResearchRequest {
  contract: typeof CONTRACT;
  template?: "company";
  params: {
    domain: string;
    /** the trading name the company confirmed when it claimed its page */
    name: string;
    /** "register:key" matches the company said are it, e.g. "uk-register:09733676" */
    confirmed?: string[];
    /** "register:key" matches the company said are not it */
    rejected?: string[];
  };
  claims: Claim[];
  /** Pages Requstory has already rendered (content a browser builds that plain
   *  HTTP never sees). Optional. Up to 150, each up to 2 MB. Send `html`: a
   *  rendered page's innerText leaves out collapsed menus, which is where product
   *  names live. Accepted only when the URL is on the company's site; off-site
   *  pages are skipped and listed in result.sources.skipped. */
  pages?: SuppliedPage[];
}

export interface SuppliedPage {
  url: string;
  /** rendered DOM (document.documentElement.outerHTML) — preferred: keeps collapsed
   *  menus, tel: links and the footer */
  html?: string;
  /** rendered text — only when html is over 2 MB; innerText drops hidden menus */
  text?: string;
  title?: string;
  /** ISO timestamp of the render; shown with the evidence */
  rendered_at?: string;
}

export interface Claim {
  id: string;
  text: string;
  /** Free-form; echoed back untouched. Requstory uses these to find the line again. */
  section?: string;
  origin?: string;
  [key: string]: unknown;
}

export type Verdict =
  /** a source other than the company's own site states it, in a sentence naming the company */
  | "corroborated"
  /** only the company's own site says it */
  | "self_reported"
  /** the words appear on the site, but only as a menu item, button or heading */
  | "label_only"
  /** nothing collected supports it — often because the foundry could not see the page */
  | "not_found";

export interface Support {
  source_id: string;
  source_type: SourceType;
  title: string;
  uri: string;
  quote: string;
  support: number;
  visibility: Visibility;
}

export interface CheckedClaim extends Claim {
  verdict: Verdict;
  note: string;
  support: Support[];
}

export interface RegisterEntity {
  name: string;
  key: string;
  /** false = matched by name only; held out of the evidence until the company confirms it */
  corroborated: boolean;
  via: "trading name" | "declared on the site" | "confirmed by the subject";
}

export interface RegisterResult {
  register: string;
  status: "resolved" | "pending_confirmation" | "unresolved" | "failed" | "not_run";
  reason?: string;
  entities?: RegisterEntity[];
}

export interface Answer {
  id: string;
  question: string;
  status: "answered" | "insufficient_evidence" | "out_of_scope" | "ambiguous" | "unsupported" | "irrelevant";
  answer: string;
  /** "register_fields", "local_extractive", or a named model */
  produced_by: string;
  sources: { source_type: SourceType; title: string; uri: string; visibility: Visibility }[];
  visibility: Visibility;
}

export interface ResearchResult {
  contract: typeof CONTRACT;
  knowledge_area: string;
  params: { domain: string; name: string };
  started_at: string;
  finished_at: string;
  seconds: { collect: number; build: number; answer: number; verify: number };
  identity: Record<string, RegisterResult>;
  registers: { publisher: string; uri: string; title: string;
               fields: Record<string, string[]>; visibility: "public" }[];
  site: {
    domain: string; redirected_from: string | null; page_uris: string[];
    pages_read: number; pages_crawled: number; pages_supplied: number;
    emails: { value: string; found_on: string }[];
    phones: { value: string; found_on: string }[];
    probes: Record<string, { present: boolean; detail: string; uri?: string }>;
    declared_names: string[];
  };
  claims: CheckedClaim[];
  answers: Answer[];
  sources: { counts: Partial<Record<SourceType, number>>; licences: string[];
             retired: string[]; skipped: { collector: string; uri: string; reason: string }[] };
  provenance: { verifier: string; answers: string };
}

export type Job =
  | { job_id: string; status: "queued" | "running" }
  | { job_id: string; status: "done"; result: ResearchResult }
  | { job_id: string; status: "failed"; error: string };
